@app.route("/apply", methods=["POST"])
def apply_submit():
    # honeypot：一般人看不到這個欄位，機器人才會填
    if (request.form.get("website") or "").strip():
        return redirect(url_for("apply_thanks"))

    ip = _client_ip()
    if not _check_rate_limit(ip):
        return render_template(
            "apply.html", error="這個小時送出次數太多了，請稍後再試一次", form=request.form
        ), 429

    name = (request.form.get("name") or "").strip()
    company = (request.form.get("company") or "").strip()
    line_id = (request.form.get("line_id") or "").strip()

    error = None
    if not name:
        error = "請填寫姓名"
    elif not company:
        error = "請填寫公司/職稱"
    elif not line_id:
        error = "請填寫您的 LINE ID，教練才能加您好友"

    if error:
        return render_template(
            "apply.html", error=error, form=request.form
        ), 400

    conn = db.get_conn()
    db.insert_application(conn, name, company, line_id)
    conn.close()
    _notify_coach_line("【百人導師申請】", name, company, line_id)

    return redirect(url_for("apply_thanks"))


